// The debug APK carries the same applicationId as the release build and a different signing key, so
// Android refuses to install it over an existing copy of the app: the only way to try a pull request
// was to uninstall the release build first, losing its configured servers with it. Giving the debug
// build its own id lets the two live side by side, and its own launcher label keeps them apart on a
// home screen where they would otherwise be the same icon under the same name.
//
// `web/android/` is generated by `cap add android` and is not versioned, so this cannot be a
// committed Gradle edit. Run it after `cap sync`, before `assembleDebug`.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs"
import path from "node:path"

const SUFFIX = ".debug"
const DEBUG_LABEL = "Harness Remote Debug"

const gradleFiles = [
  "web/android/app/build.gradle",
  "web/android/app/build.gradle.kts"
]

let targetPath = ""
let source = ""

for (const filePath of gradleFiles) {
  try {
    source = readFileSync(filePath, "utf8")
    targetPath = filePath
    break
  } catch {
    // Ignore missing file and try next candidate.
  }
}

if (!targetPath) {
  throw new Error("Android app Gradle file not found")
}

// The Kotlin DSL needs `getByName("debug") { applicationIdSuffix = "…" }`, which is not what the
// branch below writes. Capacitor's template is Groovy; if that ever changes, fail here rather than
// emit a file that will not parse.
if (targetPath.endsWith(".kts")) {
  throw new Error(`${targetPath} uses the Kotlin DSL, which this script does not generate yet`)
}

if (source.includes("applicationIdSuffix")) {
  console.log(`${targetPath} already sets an applicationIdSuffix, leaving it alone`)
} else {
  // Capacitor's template declares `buildTypes { release { … } }` and no debug block, so add one
  // rather than editing an existing entry.
  const buildTypesPattern = /(buildTypes\s*\{)/
  if (!buildTypesPattern.test(source)) {
    throw new Error(`Could not locate a buildTypes block in ${targetPath}`)
  }

  const debugBlock = `$1
        debug {
            applicationIdSuffix "${SUFFIX}"
        }`

  writeFileSync(targetPath, source.replace(buildTypesPattern, debugBlock))
  console.log(`Added applicationIdSuffix "${SUFFIX}" to the debug build type in ${targetPath}`)
}

// A `resValue` for app_name would collide with the one the main source set already declares and
// fail the build as a duplicate resource. A debug source set overrides it instead, which is what
// that source set is for.
const debugValues = path.join(path.dirname(targetPath), "src", "debug", "res", "values")
mkdirSync(debugValues, { recursive: true })

const strings = `<?xml version='1.0' encoding='utf-8'?>
<resources>
    <string name="app_name">${DEBUG_LABEL}</string>
    <string name="title_activity_main">${DEBUG_LABEL}</string>
</resources>
`

const stringsPath = path.join(debugValues, "strings.xml")
writeFileSync(stringsPath, strings)
console.log(`Wrote ${stringsPath} labelling the debug build "${DEBUG_LABEL}"`)
